import React,{FormEvent,useEffect,useState} from 'react';
import {addDays,dateKey,labelDay,monday,onDay,shiftTime} from './schedule-dates';
type Employee={id:string;name:string;employeeNumber:string;jobRole:string;maxWeeklyHours:number;allowedBranchIds:string[];primaryBranchId?:string|null;payType?:'salary'|'hourly';monthlyTargetHours?:number;allocationPriority?:number};
type Branch={id:string;name:string;timezone:string};
type Shift={id:string;employeeId:string;employeeName:string;branchId:string;branchName:string;startsAt:string;endsAt:string;breakMinutes:number;published:boolean;needsCover:boolean;hasAttendance:boolean};
type Pattern={id:string;active:boolean;employeeId:string;branchId:string;name:string;employeeName:string;branchName:string;weekdays:number[];startTime:string;endTime:string};
type Absence={id:string;employeeId:string;employeeName:string;startsAt:string;endsAt:string;category:string};
const reasons:Record<string,string>={SHIFT_OVERLAP:'Another shift overlaps',EMPLOYEE_UNAVAILABLE:'Employee is unavailable',BRANCH_NOT_ALLOWED:'Branch is outside employee eligibility',WEEKLY_HOURS_EXCEEDED:'Weekly hours limit exceeded',SHIFT_IN_PAST:'Shift is in the past',BREAK_EXCEEDS_SHIFT:'Break must be shorter than the shift',SHIFT_HAS_ATTENDANCE:'Attendance already recorded',COVER_NO_LONGER_AVAILABLE:'This employee is no longer available. Refresh cover options.',SCHEDULE_CHANGED_RETRY:'Schedule changed. Refresh and try again.',DRAFT_NOT_FOUND:'Drafts changed. Refresh and try again.',PATTERN_DUPLICATE:'This employee already has an identical active repeating pattern.',PATTERN_OVERLAP:'This employee already has an active repeating pattern with overlapping working hours.',PATTERN_HAS_SHIFTS:'This pattern has generated shifts. Stop it instead to preserve scheduling history.',BRANCH_NOT_FOUND:'Branch is unavailable',EMPLOYEE_NOT_FOUND:'Employee is unavailable'};
export function ManagerPlanner({api,token}:{api:string;token:string}){
 const [meta,setMeta]=useState<{employees:Employee[];branches:Branch[];timezone:string}>({employees:[],branches:[],timezone:'UTC'}),[week,setWeek]=useState(monday(dateKey(new Date(),'UTC'))),[shifts,setShifts]=useState<Shift[]>([]),[patterns,setPatterns]=useState<Pattern[]>([]),[absences,setAbsences]=useState<Absence[]>([]);
 const [editingDraft,setEditingDraft]=useState<Shift|null>(null);
 const [activeShift,setActiveShift]=useState<Shift|null>(null);
 const [changingShift,setChangingShift]=useState<Shift|null>(null);
 const [staffing,setStaffing]=useState([2,2,2,2,2,1,1]);
 const [hourlyStaffing,setHourlyStaffing]=useState([2,3,2]);
 const [manualDate,setManualDate]=useState('');
 const [dateFormat,setDateFormat]=useState<'DMY'|'MDY'|'YMD'>(()=>{try{const v=localStorage.getItem('attendra-rota-date-format');return v==='MDY'||v==='YMD'?v:'DMY'}catch{return 'DMY'}});
 const [showDateSettings,setShowDateSettings]=useState(false);
 const formatDate=(value:string)=>{const d=value.slice(0,10).split('-');if(d.length!==3)return value;return dateFormat==='DMY'?d[2]+'/'+d[1]+'/'+d[0]:dateFormat==='MDY'?d[1]+'/'+d[2]+'/'+d[0]:d.join('-')};
 const formatDateTime=(value:string)=>formatDate(dateKey(value,meta.timezone));
 const [rotaView,setRotaView]=useState<'week'|'month'>('week');
 const [monthlyShifts,setMonthlyShifts]=useState<Shift[]>([]);
 const [advancedOpen,setAdvancedOpen]=useState(false);
 const [monthlyGenerationResult,setMonthlyGenerationResult]=useState('');
 const policyFor=(e:Employee)=>({type:e.payType||'salary',monthlyTarget:Number(e.monthlyTargetHours??Math.round(e.maxWeeklyHours*52/12)),priority:Number(e.allocationPriority??3)});
 const savePolicy=(id:string,policy:{type:'hourly'|'salary';monthlyTarget:number;priority:number})=>void run(async()=>{const e=meta.employees.find(e=>e.id===id);if(!e)throw Error('Employee not found');await request(`scheduling/profiles/${id}`,'PUT',{jobRole:e.jobRole,maxWeeklyHours:Number(e.maxWeeklyHours),allowedBranchIds:e.allowedBranchIds,primaryBranchId:e.primaryBranchId||null,payType:policy.type,monthlyTargetHours:policy.monthlyTarget,allocationPriority:policy.priority});const updated=await request('scheduling/meta');setMeta(updated);setMessage('Employee scheduling preferences saved for the company.')});
 const [hourlyPaid,setHourlyPaid]=useState(false);
 const [operatingHours,setOperatingHours]=useState('8');
 const [shiftLength,setShiftLength]=useState('8');
 const [operatingStart,setOperatingStart]=useState('08:00');
 const [rotaBranchId,setRotaBranchId]=useState('');
 const clockAfter=(start:string,hours:number)=>{const [h,m]=start.split(':').map(Number);const mins=((h*60+m+hours*60)%1440+1440)%1440;return String(Math.floor(mins/60)).padStart(2,'0')+':'+String(mins%60).padStart(2,'0')};
 const [customShiftStart,setCustomShiftStart]=useState('08:00');
 const [customShiftEnd,setCustomShiftEnd]=useState('16:00');
 const [customOperatingEnd,setCustomOperatingEnd]=useState('16:00');
 const [daysOff,setDaysOff]=useState<Record<string,number[]>>({});
 const [balancedResult,setBalancedResult]=useState<any>(null);
 const [branchStaffingBranch,setBranchStaffingBranch]=useState('');
 const [search,setSearch]=useState(''),[branch,setBranch]=useState(''),[selected,setSelected]=useState<string[]>([]),[patternSelection,setPatternSelection]=useState<string[]>([]),[draftSelection,setDraftSelection]=useState<string[]>([]),[message,setMessage]=useState(''),[error,setError]=useState(''),[busy,setBusy]=useState(false),[loading,setLoading]=useState(true),[reload,setReload]=useState(0),[generation,setGeneration]=useState<any>(null),[cover,setCover]=useState<{shift:Shift;candidates:any[];requiredRole:string}|null>(null),[profile,setProfile]=useState<Employee|null>(null);
 const request=async(path:string,method='GET',body?:unknown,signal?:AbortSignal)=>{const r=await fetch(`${api}/v1/admin/${path}`,{method,headers:{Authorization:`Bearer ${token}`,...(body===undefined?{}:{'Content-Type':'application/json'})},body:body===undefined?undefined:JSON.stringify(body),signal});const d=await r.json();if(!r.ok)throw Error(reasons[d.error]||d.message||d.error?.replaceAll('_',' ').toLowerCase()||'Cannot load schedule');return d};
 useEffect(()=>{const abort=new AbortController();request('scheduling/meta','GET',undefined,abort.signal).then(d=>{setMeta(d);setWeek(monday(dateKey(new Date(),d.timezone)))}).catch(e=>{if(!abort.signal.aborted)setError(e.message)});return()=>abort.abort()},[api,token]);
 useEffect(()=>{const abort=new AbortController();setLoading(true);Promise.all([request(`scheduling/calendar?from=${week}&to=${addDays(week,6)}`,'GET',undefined,abort.signal),request('scheduling/patterns','GET',undefined,abort.signal),request(`scheduling/unavailability?from=${week}&to=${addDays(week,6)}`,'GET',undefined,abort.signal)]).then(([calendar,p,a])=>{setShifts(calendar.shifts);setPatterns(p.patterns);setAbsences(a.unavailability);setDraftSelection([]);if(calendar.truncated)setError('Schedule is too large. Some shifts are not displayed.');}).catch(e=>{if(!abort.signal.aborted)setError(e.message)}).finally(()=>{if(!abort.signal.aborted)setLoading(false)});return()=>abort.abort()},[api,token,week,reload]);
 const monthStart=week.slice(0,7)+'-01';
 const monthEnd=new Date(Date.UTC(Number(week.slice(0,4)),Number(week.slice(5,7)),0)).toISOString().slice(0,10);
 useEffect(()=>{if(rotaView!=='month')return;const abort=new AbortController();request(`scheduling/calendar?from=${monthStart}&to=${monthEnd}`,'GET',undefined,abort.signal).then(d=>setMonthlyShifts(d.shifts)).catch(e=>{if(!abort.signal.aborted)setError(e.message)});return()=>abort.abort()},[api,token,monthStart,monthEnd,rotaView,reload]);
 const run=async(work:()=>Promise<void>)=>{if(busy)return;setBusy(true);setError('');setMessage('');try{await work();setReload(v=>v+1)}catch(e){setError((e as Error).message)}finally{setBusy(false)}};
 const toggle=(values:string[],value:string)=>values.includes(value)?values.filter(v=>v!==value):[...values,value];
 const employees=meta.employees.filter(e=>`${e.name} ${e.employeeNumber} ${e.jobRole}`.toLowerCase().includes(search.toLowerCase())&&(!branch||!e.allowedBranchIds.length||e.allowedBranchIds.includes(branch)||shifts.some(s=>s.employeeId===e.id&&s.branchId===branch)));
 const visible=shifts.filter(s=>employees.some(e=>e.id===s.employeeId)&&(!branch||s.branchId===branch));const filteredPatterns=patterns.filter(p=>(!branch||p.branchId===branch)&&`${p.name} ${p.employeeName} ${p.branchName}`.toLowerCase().includes(search.toLowerCase()));const days=Array.from({length:7},(_,i)=>addDays(week,i));const drafts=visible.filter(s=>!s.published);const rotaEmployeeIds=new Set(visible.map(s=>s.employeeId));const rotaEmployees=employees.filter(e=>rotaEmployeeIds.has(e.id));
 const scheduledHours=(items:Shift[])=>items.reduce((sum,s)=>{const duration=(Date.parse(s.endsAt)-Date.parse(s.startsAt))/3600000-s.breakMinutes/60;return sum+Math.max(0,duration)},0);
 const employeeWeekHours=(employeeId:string)=>scheduledHours(shifts.filter(s=>s.employeeId===employeeId));
 const pendingCover=visible.filter(s=>s.needsCover&&Date.parse(s.endsAt)>Date.now());
 const pendingDrafts=drafts.filter(s=>!s.needsCover);
 const createPattern=(event:FormEvent<HTMLFormElement>)=>{event.preventDefault();const f=new FormData(event.currentTarget);void run(async()=>{const result=await request('scheduling/patterns','POST',{name:f.get('name'),branchId:f.get('branchId'),employeeIds:selected,weekdays:f.getAll('weekdays').map(Number),startTime:f.get('startTime'),endTime:f.get('endTime'),breakMinutes:Number(f.get('breakMinutes'))});setMessage(`${result.created} employee patterns saved. Generate drafts below to review them.`);setSelected([])})};
 const generate=(event:FormEvent<HTMLFormElement>)=>{event.preventDefault();const f=new FormData(event.currentTarget);void run(async()=>{const d=await request('scheduling/generate','POST',{from:f.get('from'),to:f.get('to'),patternIds:patternSelection});setGeneration(d);setMessage(`${d.created} drafts created; ${d.existing} existing shifts kept; ${d.conflicts.length} conflicts skipped; ${d.needsCover.length} drafts need cover.`)})};
 const markAbsent=(event:FormEvent<HTMLFormElement>)=>{event.preventDefault();const f=new FormData(event.currentTarget);void run(async()=>{await request('scheduling/unavailability','POST',{employeeId:f.get('employeeId'),fromDate:f.get('from'),toDate:f.get('to'),category:f.get('category')});const affected=shifts.filter(s=>s.employeeId===f.get('employeeId')&&dateKey(s.startsAt,meta.timezone)>=String(f.get('from'))&&dateKey(s.startsAt,meta.timezone)<=String(f.get('to'))&&!s.hasAttendance&&Date.parse(s.endsAt)>Date.now());if(affected.length){const first=affected[0];const options=await request(`scheduling/shifts/${first.id}/cover`);setCover({shift:first,candidates:options.candidates,requiredRole:options.requiredRole});setMessage(`Day off or absence recorded. ${affected.length} scheduled shift(s) require cover. Attendra has ranked eligible replacements for the first shift below; approve an assignment to proceed.`)}else setMessage('Availability recorded. No existing upcoming shifts require cover. Repeating patterns stay unchanged.')})};
 const loadCover=(s:Shift)=>void run(async()=>{const d=await request(`scheduling/shifts/${s.id}/cover`);setCover({shift:s,candidates:d.candidates,requiredRole:d.requiredRole})});
 const publish=()=>void run(async()=>{await request('scheduling/publish','POST',{shiftIds:draftSelection});setMessage(`${draftSelection.length} shifts published. Employees can now see them.`)});
 return <div className="planner"><section className="panel"><h2>Rota Planner</h2><p>Choose an action. Nothing is published without manager approval.</p><div className="scheduleControls"><button className="primary" type="button" onClick={()=>{document.getElementById('monthly-generator')?.scrollIntoView({behavior:'smooth'})}}>Generate Rota</button><button type="button" onClick={()=>document.getElementById('rota-create-shift')?.scrollIntoView({behavior:'smooth'})}>+ Create Shift</button><button type="button" onClick={()=>document.getElementById('rota-approvals')?.scrollIntoView({behavior:'smooth'})}>Review &amp; Publish ({pendingDrafts.length})</button></div><p>Choose Week or Month below to review the rota. Tap a day in the weekly planner to create a shift.</p><button type="button" onClick={()=>setShowDateSettings(v=>!v)} aria-expanded={showDateSettings}>⚙ Date format</button>{showDateSettings&&<label style={{display:'block',marginTop:8}}>Display dates as <select aria-label="Date format" value={dateFormat} onChange={e=>{const v=e.target.value as 'DMY'|'MDY'|'YMD';setDateFormat(v);try{localStorage.setItem('attendra-rota-date-format',v)}catch{}}}><option value="DMY">DD/MM/YYYY (21/10/2026)</option><option value="MDY">MM/DD/YYYY (10/21/2026)</option><option value="YMD">YYYY-MM-DD (2026-10-21)</option></select></label>}</section><section className="panel"><details><summary><strong>Employee pay &amp; hours preferences (planning preview)</strong></summary><p>Configure employee-specific planning preferences. These settings are saved to the company's employee profiles. Automatic allocation does not yet use pay priority or monthly target balancing.</p>{meta.employees.map(e=><form key={e.id} className="plannerForm" onSubmit={ev=>{ev.preventDefault();const f=new FormData(ev.currentTarget);savePolicy(e.id,{type:String(f.get('payType'))==='hourly'?'hourly':'salary',monthlyTarget:Number(f.get('monthlyTarget')),priority:Number(f.get('priority'))})}}><strong>{e.name}</strong><label>Pay type <select name="payType" defaultValue={policyFor(e).type}><option value="salary">Monthly salary — balance against target</option><option value="hourly">Hourly pay — manager-directed hours</option></select></label><label>Monthly target hours <input name="monthlyTarget" type="number" min="0" max="744" step="0.5" defaultValue={policyFor(e).monthlyTarget} required/></label><label>Hourly allocation priority <select name="priority" defaultValue={policyFor(e).priority}><option value="1">Low</option><option value="3">Normal</option><option value="5">High</option></select></label><button type="submit">Save planning preference</button></form>)}</details></section><section className="panel" id="monthly-generator"><h2>Generate Monthly Rota</h2><p>Choose a month, branch and staffing needs. Attendra prepares weekly draft allocations covering the selected month. Review all gaps and employee hours before publishing.</p><form className="plannerForm" onSubmit={event=>{event.preventDefault();const f=new FormData(event.currentTarget);const month=String(f.get('month'));const branchId=String(f.get('branchId'));const startTime=shiftLength==='custom'?customShiftStart:operatingStart;const endTime=shiftLength==='custom'?customShiftEnd:clockAfter(operatingStart,Number(shiftLength));const breakMinutes=hourlyPaid?Number(f.get('breakMinutes')):0;const staffingCount=Number(f.get('staffingCount'));if(!month||!branchId||!Number.isInteger(staffingCount)||staffingCount<1){setError('Select a month, branch and staffing level.');return}const first=monday(month+'-01');const last=new Date(Date.UTC(Number(month.slice(0,4)),Number(month.slice(5,7)),0)).toISOString().slice(0,10);const eligible=meta.employees.filter(e=>!e.allowedBranchIds.length||e.allowedBranchIds.includes(branchId));if(!eligible.length){setError('No eligible employees are assigned to this branch.');return}void run(async()=>{let created=0,existing=0;const gaps:string[]=[];let count=0;for(let date=first;date<=last;date=addDays(date,7)){const result=await request('scheduling/balanced-drafts','POST',{branchId,from:date,startTime,endTime,breakMinutes,staffing:Array(7).fill(staffingCount),employees:eligible.map(e=>({employeeId:e.id,daysOff:daysOff[e.id]??[],maxWeeklyHours:Number(e.maxWeeklyHours)}))});created+=result.created;existing+=result.existing;count++;for(const u of result.unmet)if(u.day>=month+'-01'&&u.day<=last)gaps.push(formatDate(u.day)+': '+(u.reason||'Staffing gap'))}setMonthlyGenerationResult(count+' weekly draft batches · '+created+' shifts created · '+existing+' existing shifts counted · '+gaps.length+' staffing warnings'+(gaps.length?' — '+gaps.slice(0,5).join('; '):''));setWeek(first);setRotaView('month');setMessage('Monthly draft generation finished. Review the month and hours before publishing.')})}}><label>Month <input name="month" type="month" defaultValue={week.slice(0,7)} required/></label><label>Branch <select name="branchId" value={rotaBranchId} onChange={e=>setRotaBranchId(e.target.value)} required><option value="" disabled>Select branch</option>{meta.branches.map(b=><option key={b.id} value={b.id}>{b.name}</option>)}</select></label><label>Staff required per day <input type="number" name="staffingCount" defaultValue={2} min={1} max={100} required/></label><fieldset style={{gridColumn:'1 / -1'}}><legend>Operating hours &amp; employee shifts</legend><p>Choose the branch's operating duration separately from each employee's shift duration. These choices apply to this draft-generation run.</p><label>Operating schedule <select aria-label="Operating schedule" value={operatingHours} onChange={e=>{const v=e.target.value;setOperatingHours(v);if(v!=='custom'&&v!=='24')setShiftLength(v);if(v==='24')setShiftLength('8')}}><option value="6">6 hours</option><option value="8">8 hours</option><option value="12">12 hours</option><option value="24">24 hours</option><option value="custom">Custom</option></select></label><label>Opening / coverage starts <input type="time" value={operatingStart} onChange={e=>setOperatingStart(e.target.value)} required/></label>{operatingHours==='custom'&&<label>Operating hours end <input type="time" value={customOperatingEnd} onChange={e=>setCustomOperatingEnd(e.target.value)} required/></label>}<label>Employee shift duration <select aria-label="Employee shift duration" value={shiftLength} onChange={e=>setShiftLength(e.target.value)}><option value="6">6 hours</option><option value="8">8 hours</option><option value="12">12 hours</option><option value="custom">Custom shift times</option></select></label>{shiftLength==='custom'?<><label>Shift starts <input type="time" value={customShiftStart} onChange={e=>setCustomShiftStart(e.target.value)} required/></label><label>Shift ends <input type="time" value={customShiftEnd} onChange={e=>setCustomShiftEnd(e.target.value)} required/></label></>:<p>Draft shift: {operatingStart}–{clockAfter(operatingStart,Number(shiftLength))}</p>}{(operatingHours==='24'||operatingHours==='12'&&Number(shiftLength)<12)&&<p role="note">This first version generates only the selected shift window, not complete {operatingHours}-hour coverage. Full multi-shift coverage requires the next scheduling-engine upgrade.</p>}</fieldset><label style={{display:'flex',alignItems:'center',gap:8}}>Hourly-paid employees <input type="checkbox" role="switch" aria-label="Hourly-paid employees" checked={hourlyPaid} onChange={e=>setHourlyPaid(e.target.checked)}/><span>{hourlyPaid?'On':'Off'}</span></label>{hourlyPaid&&<label>Unpaid break deduction (minutes) <input type="number" name="breakMinutes" defaultValue={60} min={0} max={720} required/></label>}<p style={{fontSize:12}}>For monthly-paid employees, no break time is deducted from scheduled hours. Rest breaks still apply according to company policy and employment law.</p><button className="primary" disabled={busy}>Generate monthly drafts</button></form>{monthlyGenerationResult&&<p role="status">{monthlyGenerationResult}</p>}<p style={{fontSize:12}}>Initial version: uses existing weekly allocation rules to generate drafts for the month. It does not yet save a recurring monthly template, rotate intraday shifts, or optimise monthly fairness. Weeks overlapping adjacent months may also receive drafts; check them before publishing. Use Advanced Options for custom weekday staffing and days off.</p></section><div id="rota-approvals"><section className="panel" aria-label="Manager approval centre"><h2>Manager Approval Centre</h2><p>Attendra prepares recommendations and drafts. Only the manager can approve replacements or publish shifts.</p><div className="scheduleControls"><strong>{pendingDrafts.length} drafts ready for review</strong><strong>{pendingCover.length} shifts needing cover</strong></div>{pendingDrafts.length>0&&<div className="scheduleControls"><button disabled={busy} onClick={()=>setDraftSelection([...new Set(pendingDrafts.map(s=>s.id))].slice(0,500))}>Select up to 500 drafts</button><button className="primary" disabled={busy||draftSelection.length===0||draftSelection.length>500} onClick={publish}>Approve and publish {draftSelection.length} selected</button></div>}{pendingCover.map(s=><div className="attendanceRow" key={s.id}><div><strong>{s.employeeName} · Cover needed</strong><p>{s.branchName} · {formatDateTime(s.startsAt)} · {shiftTime(s,meta.timezone)}</p></div><button disabled={busy} onClick={()=>loadCover(s)}>Review replacements</button></div>)}{pendingCover.length===0&&pendingDrafts.length===0&&<p>No pending shift approvals for this week.</p>}<p>Days off and absences flag affected shifts for manager review; recording an exception does not authorize a replacement.</p></section></div><section className="panel"><div className="panelHead"><div><h2>Rota calendar</h2><span>{rotaView==='week'?formatDate(week)+' – '+formatDate(addDays(week,6)):formatDate(monthStart)+' – '+formatDate(monthEnd)} · {meta.timezone}</span><div className="scheduleControls"><button type="button" aria-pressed={rotaView==='week'} onClick={()=>setRotaView('week')}>Week</button><button type="button" aria-pressed={rotaView==='month'} onClick={()=>setRotaView('month')}>Month</button></div></div><div className="scheduleControls"><button disabled={busy} onClick={()=>setWeek(addDays(week,-7))}>← Previous</button><button onClick={()=>setWeek(monday(dateKey(new Date(),meta.timezone)))}>This week</button><button disabled={busy} onClick={()=>setWeek(addDays(week,7))}>Next →</button></div></div><div className="directoryTools"><input aria-label="Search employees" placeholder="Search name, number or role" value={search} onChange={e=>setSearch(e.target.value)}/><select aria-label="Branch filter" value={branch} onChange={e=>setBranch(e.target.value)}><option value="">All branches</option>{meta.branches.map(b=><option key={b.id} value={b.id}>{b.name}</option>)}</select><button disabled={busy} onClick={()=>setReload(v=>v+1)}>Refresh</button></div>{error&&<div role="alert" className="errorBox">{error}</div>}{message&&<div role="status" className="infoBox">{message}</div>}{rotaView==='month'?<div><h3>Monthly rota overview</h3><p>Read-only monthly summary across all branches. Click a date to edit shifts in the weekly planner. This does not yet create or repeat a monthly template.</p><div style={{display:'grid',gridTemplateColumns:'repeat(7,minmax(0,1fr))',gap:4}}>{['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=><strong key={d} style={{textAlign:'center',fontSize:11}}>{d}</strong>)}{Array.from({length:((new Date(monthStart+'T00:00:00Z').getUTCDay()+6)%7)},(_,i)=><span key={'pad'+i}/>)}{Array.from({length:Number(monthEnd.slice(-2))},(_,i)=>{const day=monthStart.slice(0,8)+String(i+1).padStart(2,'0');const dayShifts=monthlyShifts.filter(x=>dateKey(x.startsAt,meta.timezone)===day&&(!branch||x.branchId===branch));return <button key={day} type="button" title={formatDate(day)} onClick={()=>{setWeek(monday(day));setRotaView('week')}} style={{minHeight:65,padding:4,textAlign:'left',border:'1px solid #94a3b8',borderRadius:6,background:'transparent',color:'inherit'}}><strong>{i+1}</strong><div style={{fontSize:11}}>{dayShifts.length} shifts</div><div style={{fontSize:10}}>{dayShifts.filter(x=>!x.published).length} drafts</div></button>})}</div><h3>Monthly scheduled hours</h3><p>Draft and published hours are included. Target-hour comparisons use employee scheduling profiles, not payroll records. Exceeding a target is a planning warning, not a legal overtime determination. Actual attendance hours are not yet included.</p><div style={{overflowX:'auto'}}><table style={{width:'100%',fontSize:13}}><thead><tr><th>Employee</th><th>Pay type</th><th>Scheduled hours</th><th>Target hours</th><th>Variance</th><th>Shifts</th></tr></thead><tbody>{employees.map(e=>{const es=monthlyShifts.filter(x=>x.employeeId===e.id);return <tr key={e.id}><td>{e.name}</td><td>{policyFor(e).type==='hourly'?'Hourly':'Monthly salary'}</td><td style={{textAlign:'center'}}>{scheduledHours(es).toFixed(1)}h</td><td style={{textAlign:'center'}}>{policyFor(e).monthlyTarget}h</td><td style={{textAlign:'center',fontWeight:scheduledHours(es)>policyFor(e).monthlyTarget?700:400}}>{(scheduledHours(es)-policyFor(e).monthlyTarget)>0?'+':''}{(scheduledHours(es)-policyFor(e).monthlyTarget).toFixed(1)}h{scheduledHours(es)>policyFor(e).monthlyTarget?' ⚠':''}</td><td style={{textAlign:'center'}}>{es.length}</td></tr>})}</tbody></table></div></div>:loading?<p>Loading planner…</p>:<div className="plannerScroll"><table className="plannerTable" style={{tableLayout:"fixed",width:"100%",minWidth:0,fontSize:11}}><thead><tr><th style={{width:"18%",padding:3}}>Employee</th>{days.map(d=><th key={d} style={{width:"11.7%",padding:2,fontSize:10}}><button type="button" title="Create shift on this date" onClick={()=>{setManualDate(d);document.getElementById('rota-create-shift')?.scrollIntoView({behavior:'smooth'})}} style={{border:0,background:'transparent',color:'inherit',font:'inherit',fontWeight:700,padding:2}}>{formatDate(d)} +</button></th>)}</tr></thead><tbody>{rotaEmployees.map(e=><tr key={e.id}><th style={{padding:3,overflowWrap:"anywhere",fontSize:11}}><strong>{e.name}</strong><button type="button" title="Scheduling rules" aria-label={"Scheduling rules for "+e.name} style={{display:"block",padding:"2px 4px",fontSize:10}} onClick={()=>setProfile(e)}>⚙ Rules</button></th>{days.map(day=><td style={{padding:2,verticalAlign:"top"}} key={day}>{absences.some(a=>a.employeeId===e.id&&onDay(a,day,meta.timezone))&&<span className="scheduleWarning">Unavailable</span>}{visible.filter(s=>s.employeeId===e.id&&onDay(s,day,meta.timezone)).map(s=><button type="button" key={s.id} onClick={()=>setActiveShift(s)} title={s.branchName+' · '+shiftTime(s,meta.timezone)+' · '+(s.published?'Published':'Draft')} aria-label={'Open shift '+shiftTime(s,meta.timezone)+' for '+e.name} style={{display:'block',width:'100%',minWidth:0,padding:'5px 2px',margin:'2px 0',border:s.published?'1px solid #6b7280':'1px dashed #64748b',borderRadius:5,background:activeShift?.id===s.id?'#dbeafe':'transparent',color:'inherit',fontSize:11,lineHeight:1.2,textAlign:'center',whiteSpace:'normal'}}><span style={{display:'block',fontWeight:700}}>{shiftTime(s,meta.timezone)}</span><span style={{display:'block',fontSize:10}}>{s.needsCover?'Cover!':s.published?'✓':'Draft'}</span></button>)}</td>)}</tr>)}</tbody></table>{employees.length===0&&<p>No employees match this view.</p>}</div>}<div style={{marginTop:12}}><h3>Employee hours · selected week</h3><p style={{fontSize:12}}>Scheduled hours only (published and draft shifts). Actual worked hours require attendance reconciliation. Totals include all branches, even when a branch filter is selected.</p><div style={{overflowX:'auto'}}><table style={{width:'100%',fontSize:13}}><thead><tr><th style={{textAlign:'left'}}>Employee</th><th>Scheduled</th><th>Weekly limit</th><th>Remaining</th></tr></thead><tbody>{employees.map(e=>{const h=employeeWeekHours(e.id);return <tr key={e.id}><td>{e.name}</td><td style={{textAlign:'center'}}>{h.toFixed(1)}h</td><td style={{textAlign:'center'}}>{e.maxWeeklyHours}h</td><td style={{textAlign:'center',color:h>e.maxWeeklyHours?'#dc2626':'inherit'}}>{(e.maxWeeklyHours-h).toFixed(1)}h</td></tr>})}</tbody></table></div></div>{activeShift&&<div className="panel" style={{padding:12,marginTop:8}}><div style={{display:'flex',justifyContent:'space-between',alignItems:'center',gap:8}}><strong>{activeShift.employeeName} · {shiftTime(activeShift,meta.timezone)} · {activeShift.published?'Published':'Draft'}</strong><button type="button" onClick={()=>setActiveShift(null)} aria-label="Close shift actions">✕</button></div><small>{activeShift.branchName}</small><div className="scheduleControls" style={{display:'flex',gap:6,flexWrap:'wrap',marginTop:8}}>{!activeShift.hasAttendance&&Date.parse(activeShift.endsAt)>Date.now()&&<button disabled={busy} onClick={()=>loadCover(activeShift)}>⇄ Replace</button>}{activeShift.published&&Date.parse(activeShift.startsAt)>Date.now()&&!activeShift.hasAttendance&&<><button disabled={busy} onClick={()=>setChangingShift(activeShift)}>✎ Change</button><button disabled={busy} onClick={()=>{if(!window.confirm('Remove this future published shift? The employee will be notified.'))return;void run(async()=>{await request(`scheduling/shifts/${activeShift.id}/remove`,'DELETE');setActiveShift(null);setMessage('Future shift removed. Employee notified.')})}}>✕ Remove</button></>}{!activeShift.published&&<><label className="checkLabel"><input type="checkbox" checked={draftSelection.includes(activeShift.id)} onChange={()=>setDraftSelection(toggle(draftSelection,activeShift.id))}/>Select to publish</label><button disabled={busy} onClick={()=>setEditingDraft(activeShift)}>✎ Edit</button><button disabled={busy} onClick={()=>void run(async()=>{await request(`shifts/${activeShift.id}`,'DELETE');setActiveShift(null);setMessage('Draft deleted.')})}>✕ Delete</button></>}</div></div>}{drafts.length>0&&<div className="scheduleControls"><button disabled={busy} onClick={()=>setDraftSelection([...new Set(drafts.filter(s=>!s.needsCover).map(s=>s.id))].slice(0,500))}>Select publishable drafts (up to 500)</button><button className="primary" disabled={busy||!draftSelection.length||draftSelection.length>500} onClick={publish}>Publish {draftSelection.length} selected</button><button type="button" disabled={busy} title="Delete all unpublished drafts for this week and selected branch" onClick={()=>{const scoped=drafts.filter(s=>!branch||s.branchId===branch);if(!scoped.length)return;const scope=branch?meta.branches.find(b=>b.id===branch)?.name||'selected branch':'all branches';if(!window.confirm(`Undo all ${scoped.length} unpublished draft shifts for the week of ${week} in ${scope}? Published shifts will remain unchanged. This cannot be undone.`))return;void run(async()=>{const result=await request('scheduling/undo-week-drafts','POST',{from:week,...(branch?{branchId:branch}:{})});setActiveShift(null);setDraftSelection([]);setMessage(`${result.deleted} draft shifts cleared. Published shifts remain unchanged.`)})}}>↶ Undo all drafts</button><span>Employees see shifts after publication.</span></div>}</section>
 <section className="panel"><h2>Select employees for assignment</h2><p>Use the search and branch filters above, then select employees for a one-off shift or repeating pattern.</p><fieldset><legend>Employees · {selected.length} selected</legend><button type="button" onClick={()=>setSelected([...new Set([...selected,...employees.map(e=>e.id)])].slice(0,500))}>Select filtered employees</button><button type="button" onClick={()=>setSelected([])}>Clear</button><div className="employeePicker">{employees.map(e=><label className="checkLabel" key={e.id}><input type="checkbox" checked={selected.includes(e.id)} onChange={()=>setSelected(toggle(selected,e.id))}/>{e.name} · #{e.employeeNumber}</label>)}</div></fieldset><p>{selected.length} selected across all filters.</p></section>
 {changingShift&&<section className="panel" aria-label="Change published shift"><div className="panelHead"><h2>Change or replace published shift</h2><button type="button" onClick={()=>setChangingShift(null)}>Close</button></div><p>Change times, date or branch, or select another employee to replace the assigned worker. The affected employees will be notified. Use One-off shift below to add a second employee without replacing anyone.</p><form className="plannerForm" key={changingShift.id} onSubmit={event=>{event.preventDefault();const f=new FormData(event.currentTarget);void run(async()=>{await request(`scheduling/shifts/${changingShift.id}/change`,'PUT',{employeeId:f.get('employeeId'),branchId:f.get('branchId'),date:f.get('date'),startTime:f.get('startTime'),endTime:f.get('endTime'),breakMinutes:Number(f.get('breakMinutes'))});setChangingShift(null);setMessage('Published shift changed. Employees notified.')})}}><label>Employee / replacement<select name="employeeId" defaultValue={changingShift.employeeId} required>{meta.employees.map(e=><option key={e.id} value={e.id}>{e.name} · #{e.employeeNumber}</option>)}</select></label><label>Branch<select name="branchId" defaultValue={changingShift.branchId} required>{meta.branches.map(b=><option key={b.id} value={b.id}>{b.name}</option>)}</select></label><label>Date<input name="date" type="date" defaultValue={dateKey(changingShift.startsAt,meta.timezone)} required/></label><label>Start<input name="startTime" type="time" defaultValue={new Date(changingShift.startsAt).toLocaleTimeString('en-GB',{timeZone:meta.timezone,hour:'2-digit',minute:'2-digit',hour12:false})} required/></label><label>End<input name="endTime" type="time" defaultValue={new Date(changingShift.endsAt).toLocaleTimeString('en-GB',{timeZone:meta.timezone,hour:'2-digit',minute:'2-digit',hour12:false})} required/></label><label>Break minutes<input name="breakMinutes" type="number" min="0" max="720" defaultValue={changingShift.breakMinutes} required/></label><button className="primary" disabled={busy}>Save published shift changes</button></form></section>}
 {editingDraft&&<section className="panel" aria-label="Edit draft shift"><div className="panelHead"><h2>Edit unpublished shift</h2><button type="button" onClick={()=>setEditingDraft(null)}>Close</button></div><p>Changes affect only this draft, not its repeating pattern. The manager must still publish it.</p><form className="plannerForm" key={editingDraft.id} onSubmit={event=>{event.preventDefault();const f=new FormData(event.currentTarget);void run(async()=>{await request(`scheduling/shifts/${editingDraft.id}/draft`,'PUT',{employeeId:f.get('employeeId'),branchId:f.get('branchId'),date:f.get('date'),startTime:f.get('startTime'),endTime:f.get('endTime'),breakMinutes:Number(f.get('breakMinutes'))});setEditingDraft(null);setMessage('Draft updated. Review before publishing.')})}}><label>Employee<select name="employeeId" defaultValue={editingDraft.employeeId} required>{meta.employees.map(e=><option key={e.id} value={e.id}>{e.name} · #{e.employeeNumber}</option>)}</select></label><label>Branch<select name="branchId" defaultValue={editingDraft.branchId} required>{meta.branches.map(b=><option key={b.id} value={b.id}>{b.name}</option>)}</select></label><label>Date<input name="date" type="date" defaultValue={dateKey(editingDraft.startsAt,meta.timezone)} required/></label><label>Start<input name="startTime" type="time" defaultValue={new Date(editingDraft.startsAt).toLocaleTimeString('en-GB',{timeZone:meta.timezone,hour:'2-digit',minute:'2-digit',hour12:false})} required/></label><label>End<input name="endTime" type="time" defaultValue={new Date(editingDraft.endsAt).toLocaleTimeString('en-GB',{timeZone:meta.timezone,hour:'2-digit',minute:'2-digit',hour12:false})} required/></label><label>Break minutes<input name="breakMinutes" type="number" min="0" max="720" defaultValue={editingDraft.breakMinutes} required/></label><button className="primary" disabled={busy}>Save draft changes</button></form></section>}
 {cover&&<section className="panel" aria-label="Shift cover"><div className="panelHead"><h2>Cover for {cover.shift.employeeName}</h2><button onClick={()=>setCover(null)}>Close</button></div><p>{cover.shift.branchName} · {new Date(cover.shift.startsAt).toLocaleString(undefined,{timeZone:meta.timezone})} · {shiftTime(cover.shift,meta.timezone)}</p><p>{cover.requiredRole?`Matching role: ${cover.requiredRole}`:'No role is set for this employee. Set scheduling rules to narrow suggestions.'} Candidates have no overlapping shifts or availability exceptions and fit their branch eligibility and weekly hours limit.</p>{cover.candidates.length===0?<p>No eligible employees found. Review availability and scheduling rules.</p>:cover.candidates.map((c,i)=><div className="attendanceRow" key={c.employeeId}><div><strong>{c.name}{i===0?' · Recommended by Attendra':''}</strong><p>{c.jobRole||'Role not set'} · {Number(c.scheduledHours).toFixed(1)} / {c.maxWeeklyHours} hours scheduled this week</p></div><button className="primary" disabled={busy} onClick={()=>void run(async()=>{await request(`scheduling/shifts/${cover.shift.id}/cover`,'POST',{employeeId:c.employeeId});setCover(null);setMessage('Cover assigned. The recurring pattern is unchanged.')})}>Assign cover</button></div>)}</section>}
 {profile&&<section className="panel"><div className="panelHead"><h2>Scheduling rules · {profile.name}</h2><button onClick={()=>setProfile(null)}>Close</button></div><form className="plannerForm" key={profile.id} onSubmit={event=>{event.preventDefault();const f=new FormData(event.currentTarget);void run(async()=>{await request(`scheduling/profiles/${profile.id}`,'PUT',{jobRole:f.get('jobRole'),maxWeeklyHours:Number(f.get('maxWeeklyHours')),allowedBranchIds:f.getAll('branches')});const d=await request('scheduling/meta');setMeta(d);setProfile(null);setMessage('Scheduling rules saved.')})}}><label>Role<input name="jobRole" defaultValue={profile.jobRole} maxLength={100} placeholder="e.g. Barista"/></label><label>Maximum weekly hours<input name="maxWeeklyHours" type="number" min="1" max="168" step="0.5" defaultValue={profile.maxWeeklyHours} required/></label><fieldset><legend>Eligible branches (none selected means all)</legend>{meta.branches.map(b=><label className="checkLabel" key={b.id}><input name="branches" type="checkbox" value={b.id} defaultChecked={profile.allowedBranchIds.includes(b.id)}/>{b.name}</label>)}</fieldset><button className="primary" disabled={busy}>Save rules</button></form></section>}
 <section className="panel"><h2>Branch Staffing</h2><p>Select a branch to see its assigned team. Edit each employee's branch assignments using the employee controls below.</p><label>Branch <select value={branchStaffingBranch} onChange={e=>setBranchStaffingBranch(e.target.value)}><option value="">Select branch</option>{meta.branches.map(b=><option key={b.id} value={b.id}>{b.name}</option>)}</select></label>{branchStaffingBranch&&<div><h3>Assigned team · {meta.branches.find(b=>b.id===branchStaffingBranch)?.name}</h3>{meta.employees.filter(e=>e.allowedBranchIds.includes(branchStaffingBranch)).length===0?<p>No employees explicitly assigned to this branch yet.</p>:<div style={{display:'grid',gap:6}}>{meta.employees.filter(e=>e.allowedBranchIds.includes(branchStaffingBranch)).map(e=><div key={e.id} style={{display:'flex',justifyContent:'space-between',alignItems:'center',border:'1px solid #ddd',borderRadius:6,padding:8}}><span><strong>{e.name}</strong> · #{e.employeeNumber} · {e.jobRole||'Role not set'} {e.primaryBranchId===branchStaffingBranch?'· Primary':''}</span><button type="button" onClick={()=>setProfile(e)}>Edit employee branches</button></div>)}</div>}</div>}<details style={{marginTop:12}}><summary>Employee branch assignments</summary><p>Select one or more eligible branches for each employee and choose their primary branch.</p>{meta.employees.map(e=><form key={e.id} style={{borderBottom:'1px solid #ddd',padding:'8px 0'}} onSubmit={event=>{event.preventDefault();const f=new FormData(event.currentTarget);const ids=f.getAll('eligibleBranches').map(String);const primary=String(f.get('primaryBranchId')||'');if(primary&&!ids.includes(primary)){setError('The primary branch must also be selected as an eligible branch.');return}void run(async()=>{await request(`scheduling/profiles/${e.id}`,'PUT',{jobRole:e.jobRole,maxWeeklyHours:Number(e.maxWeeklyHours),allowedBranchIds:ids,primaryBranchId:primary||null});const d=await request('scheduling/meta');setMeta(d);setMessage(`Branch staffing saved for ${e.name}.`)})}}><strong>{e.name} · #{e.employeeNumber}</strong><div style={{display:'flex',flexWrap:'wrap',gap:10,margin:'6px 0'}}>{meta.branches.map(b=><label key={b.id} className="checkLabel"><input type="checkbox" name="eligibleBranches" value={b.id} defaultChecked={e.allowedBranchIds.includes(b.id)}/>{b.name}</label>)}</div><label>Primary branch <select name="primaryBranchId" defaultValue={e.primaryBranchId||''}><option value="">No preference</option>{meta.branches.map(b=><option value={b.id} key={b.id}>{b.name}</option>)}</select></label><button type="submit" disabled={busy}>Save branch assignments</button></form>)}</details></section>
<section className="panel" id="rota-create-shift"><h2>Create Shift</h2><p>Create opening, midday, closing or overlapping shifts for individual employees. Use Edit on an existing draft to shorten, extend, move or replace it; add another draft for the second half of a split shift. Attendra checks cross-branch overlaps, availability and weekly limits. Publishing always requires manager approval.</p><form className="plannerForm" onSubmit={event=>{event.preventDefault();const f=new FormData(event.currentTarget);void run(async()=>{const d=await request('scheduling/drafts','POST',{employeeIds:f.getAll('manualEmployees').map(String),branchId:f.get('branchId'),date:f.get('date'),startTime:f.get('startTime'),endTime:f.get('endTime'),breakMinutes:Number(f.get('breakMinutes'))});setMessage(`${d.created} manual shift drafts created. Review before publishing.`)})}}><label>Branch<select name="branchId" required defaultValue=""><option value="" disabled>Select branch</option>{meta.branches.map(b=><option key={b.id} value={b.id}>{b.name} · {b.timezone}</option>)}</select></label><fieldset><legend>Employees for this shift</legend><div className="scheduleControls">{meta.employees.map(e=><label key={e.id} className="checkLabel"><input name="manualEmployees" type="checkbox" value={e.id}/>{e.name} · #{e.employeeNumber}</label>)}</div></fieldset><label>Date<input type="date" name="date" key={manualDate||week} defaultValue={manualDate||week} required/></label><label>Start<input type="time" name="startTime" defaultValue="08:00" required/></label><label>End<input type="time" name="endTime" defaultValue="17:00" required/></label><label>Break minutes<input type="number" name="breakMinutes" defaultValue="60" min="0" max="720" required/></label><button className="primary" disabled={busy}>Create manual draft shifts</button></form></section>
 <section className="panel"><button type="button" aria-expanded={advancedOpen} onClick={()=>setAdvancedOpen(v=>!v)}>{advancedOpen?'▾ Hide advanced options':'▸ Advanced Options'}</button><p>Hourly staffing, patterns, balanced generation and absences.</p></section>{advancedOpen&&<div id="rota-generator"><section className="panel"><h2>Hourly staffing plan</h2><p>Set how many employees should be on duty during each part of the day. Use this as a guide when creating manual or hybrid draft shifts. These requirements are a planning preview and are not yet used by automatic generation.</p><div style={{display:'grid',gridTemplateColumns:'repeat(auto-fit,minmax(170px,1fr))',gap:8}}>{[{label:'Opening · 08:00–11:00',index:0},{label:'Midday · 11:00–14:00',index:1},{label:'Closing · 14:00–17:00',index:2}].map(slot=><div key={slot.index} style={{border:'1px solid #9ca3af',borderRadius:8,padding:8}}><strong>{slot.label}</strong><div style={{display:'flex',alignItems:'center',gap:8,marginTop:6}}><button type="button" disabled={hourlyStaffing[slot.index]<=0} onClick={()=>setHourlyStaffing(v=>v.map((n,i)=>i===slot.index?Math.max(0,n-1):n))}>−</button><strong>{hourlyStaffing[slot.index]}</strong><button type="button" onClick={()=>setHourlyStaffing(v=>v.map((n,i)=>i===slot.index?Math.min(100,n+1):n))}>+</button></div></div>)}</div></section>
<section className="panel"><h2>Repeating shift patterns</h2><p>Assign one weekly pattern to several employees. Generate drafts for a date range, resolve conflicts, then publish. Times use the selected branch’s timezone; an end time earlier than the start means an overnight shift.</p><form className="plannerForm" onSubmit={createPattern}><label>Pattern name<input name="name" required maxLength={100} placeholder="Morning team"/></label><label>Branch<select name="branchId" required defaultValue=""><option value="" disabled>Select branch</option>{meta.branches.map(b=><option value={b.id} key={b.id}>{b.name} · {b.timezone}</option>)}</select></label><label>Start time<input name="startTime" type="time" defaultValue="08:00" required/></label><label>End time<input name="endTime" type="time" defaultValue="17:00" required/></label><label>Break minutes<input name="breakMinutes" type="number" defaultValue="60" min="0" max="720" required/></label><fieldset><legend>Repeat on</legend><div className="scheduleControls">{['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map((day,i)=><label className="checkLabel" key={day}><input type="checkbox" name="weekdays" value={i+1} defaultChecked={i<5}/>{day}</label>)}</div></fieldset><button className="primary" disabled={busy||!selected.length||selected.length>500}>Save pattern for {selected.length} employees</button></form></section>
 <section className="panel"><h2>Balanced weekly rota drafts</h2><p>Set daily staffing and recurring days off. Attendra proposes an equitable allocation without exceeding hours or availability. Review and publish drafts manually. Settings entered here apply to this generation; permanent saved rules will follow in a separate upgrade.</p><form className="plannerForm" onSubmit={event=>{event.preventDefault();const f=new FormData(event.currentTarget);const employeeIds=meta.employees.filter(e=>!branch||e.allowedBranchIds.length===0||e.allowedBranchIds.includes(branch)).map(e=>e.id);void run(async()=>{const result=await request('scheduling/balanced-drafts','POST',{branchId:f.get('branchId'),from:f.get('from'),startTime:f.get('startTime'),endTime:f.get('endTime'),breakMinutes:Number(f.get('breakMinutes')),staffing,employees:meta.employees.filter(e=>employeeIds.includes(e.id)).map(e=>({employeeId:e.id,daysOff:daysOff[e.id]??(e.employeeNumber==='Test001'||e.employeeNumber==='Test002'?[6,7]:e.employeeNumber==='Test003'?[1,2]:e.employeeNumber==='Test004'?[3,4]:e.employeeNumber==='Test005'?[4,5]:[]),maxWeeklyHours:Number(e.maxWeeklyHours)}))});setBalancedResult(result);setMessage(`${result.created} balanced drafts created; ${result.unmet.length} days have staffing gaps. Review drafts before publishing.`)})}}><label>Branch<select name="branchId" required defaultValue=""><option value="" disabled>Select branch</option>{meta.branches.map(b=><option key={b.id} value={b.id}>{b.name}</option>)}</select></label><label>Week beginning Monday<input type="date" name="from" required defaultValue={week} key={'balanced'+week}/></label><label>Start<input name="startTime" type="time" defaultValue="08:00" required/></label><label>End<input name="endTime" type="time" defaultValue="17:00" required/></label><label>Unpaid break minutes<input name="breakMinutes" type="number" defaultValue="60" min="0" max="720" required/></label><fieldset><legend>Required employees each day</legend><div style={{display:'grid',gridTemplateColumns:'repeat(auto-fit,minmax(145px,1fr))',gap:8}}>{['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map((d,i)=><div key={d} style={{display:'flex',alignItems:'center',justifyContent:'space-between',gap:6,border:'1px solid #9ca3af',borderRadius:8,padding:'6px 8px'}}><strong>{d}</strong><div style={{display:'flex',alignItems:'center',gap:5}}><button type="button" title={'Remove one '+d+' staff member'} aria-label={'Decrease '+d+' staffing'} disabled={staffing[i]<=0} onClick={()=>setStaffing(v=>v.map((x,j)=>j===i?Math.max(0,x-1):x))} style={{minWidth:30,minHeight:32,padding:'2px 7px'}}>−</button><input type="number" aria-label={d+' required staff'} min="0" max="100" value={staffing[i]} onChange={e=>setStaffing(v=>v.map((x,j)=>j===i?Math.max(0,Math.min(100,Number(e.target.value)||0)):x))} style={{width:46,minWidth:0,textAlign:'center',padding:'4px 2px'}}/><button type="button" title={'Add one '+d+' staff member'} aria-label={'Increase '+d+' staffing'} disabled={staffing[i]>=100} onClick={()=>setStaffing(v=>v.map((x,j)=>j===i?Math.min(100,x+1):x))} style={{minWidth:30,minHeight:32,padding:'2px 7px'}}>+</button></div></div>)}</div></fieldset><fieldset><legend>Recurring days off (checked means unavailable)</legend>{meta.employees.map(e=><div key={e.id}><strong>{e.name} · #{e.employeeNumber} · {e.maxWeeklyHours} hours/week</strong><div className="scheduleControls">{['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map((d,i)=>{const defaultOff=e.employeeNumber==='Test001'||e.employeeNumber==='Test002'?[6,7]:e.employeeNumber==='Test003'?[1,2]:e.employeeNumber==='Test004'?[3,4]:e.employeeNumber==='Test005'?[4,5]:[];const off=daysOff[e.id]??defaultOff;return <label className="checkLabel" key={d}><input type="checkbox" checked={off.includes(i+1)} onChange={()=>setDaysOff(v=>({...v,[e.id]:off.includes(i+1)?off.filter(n=>n!==i+1):[...off,i+1]}))}/>{d}</label>})}</div></div>)}</fieldset><button className="primary" disabled={busy}>Generate balanced drafts for review</button></form>{balancedResult&&<div className="generationResults"><p>{balancedResult.created} drafts created · {balancedResult.existing} existing shifts counted</p>{balancedResult.unmet.map((u:any)=><p className="scheduleWarning" key={u.day}>{u.day}: {u.reason==='EXCESS_EXISTING_SHIFTS'?`${u.excess} excess existing shift(s) — review and remove manually before publishing`:`${u.needed} positions unfilled (${u.reason})`}</p>)}</div>}</section>
 <section className="panel"><h2>Generate draft schedule</h2><form className="plannerForm" onSubmit={generate}><label>From<input type="date" name="from" required defaultValue={week} key={'from'+week}/></label><label>Through<input type="date" name="to" required defaultValue={addDays(week,6)} key={'to'+week}/></label><fieldset><legend>Patterns · {patternSelection.length} selected</legend><button type="button" onClick={()=>setPatternSelection(filteredPatterns.filter(p=>p.active).map(p=>p.id).slice(0,1000))}>Select filtered patterns (up to 1,000)</button><button type="button" onClick={()=>setPatternSelection([])}>Clear</button><div className="employeePicker">{filteredPatterns.map(p=><div className="patternChoice" key={p.id}><label className="checkLabel"><input type="checkbox" disabled={!p.active} checked={patternSelection.includes(p.id)} onChange={()=>setPatternSelection(toggle(patternSelection,p.id))}/>{p.name} · {p.employeeName} · {p.branchName} · {p.startTime.slice(0,5)}–{p.endTime.slice(0,5)}</label>{p.active?<button type="button" disabled={busy} onClick={()=>void run(async()=>{await request(`scheduling/patterns/${p.id}`,'DELETE');setPatternSelection(v=>v.filter(x=>x!==p.id));setMessage('Pattern stopped. Existing shifts are kept.')})}>Stop pattern</button>:<span>Stopped</span>}<button type="button" disabled={busy} onClick={()=>{if(!window.confirm('Permanently delete this unused pattern? This cannot be undone. Patterns linked to shifts cannot be deleted.'))return;void run(async()=>{await request(`scheduling/patterns/${p.id}/permanent`,'DELETE');setPatternSelection(v=>v.filter(x=>x!==p.id));setMessage('Unused pattern permanently deleted.')})}}>Delete permanently</button></div>)}</div></fieldset><button className="primary" disabled={busy||!patternSelection.length}>Generate drafts</button></form>{generation&&<div className="generationResults"><p>{generation.created} drafts created · {generation.existing} already exist · {generation.conflicts.length} skipped conflicts · {generation.needsCover.length} drafts need cover</p>{generation.needsCover.length>0&&<p className="scheduleWarning">Unavailable employees’ shifts were kept as drafts. Find cover in the relevant week before publishing.</p>}{generation.conflicts.length>0&&<details open><summary>Review skipped shifts</summary><p>These shifts were not created. Resolve availability or edit the pattern and generate again.</p>{generation.conflicts.map((c:any,i:number)=><p key={i}><strong>{c.employeeName}</strong> · {c.branchName} · {new Date(c.startsAt).toLocaleString(undefined,{timeZone:meta.timezone})} · {reasons[c.reason]||c.reason}</p>)}</details>}</div>}</section>
 <section className="panel"><h2>Absence, leave and days off</h2><p>Record a date exception without changing the employee’s repeating pattern. Dates include the whole day in {meta.timezone}.</p><form className="plannerForm" onSubmit={markAbsent}><label>Employee<select name="employeeId" required defaultValue=""><option value="" disabled>Select employee</option>{meta.employees.map(e=><option key={e.id} value={e.id}>{e.name} · #{e.employeeNumber}</option>)}</select></label><label>Reason<select name="category"><option value="ABSENCE">Absence</option><option value="INJURY">Injury</option><option value="LEAVE">Leave</option><option value="DAY_OFF">Day off</option></select></label><label>From<input type="date" name="from" defaultValue={week} required/></label><label>Through<input type="date" name="to" defaultValue={week} required/></label><button className="primary" disabled={busy}>Record exception</button></form>{absences.map(a=><div className="attendanceRow" key={a.id}><div><strong>{a.employeeName}</strong><p>{a.category.replaceAll('_',' ')} · {labelDay(dateKey(a.startsAt,meta.timezone))} – {labelDay(dateKey(new Date(Date.parse(a.endsAt)-1),meta.timezone))}</p></div><button disabled={busy} onClick={()=>{const affected=shifts.filter(s=>s.employeeId===a.employeeId&&Date.parse(s.startsAt)<Date.parse(a.endsAt)&&Date.parse(s.endsAt)>Date.parse(a.startsAt));const hasCover=affected.length===0&&shifts.some(s=>s.employeeId!==a.employeeId&&Date.parse(s.startsAt)<Date.parse(a.endsAt)&&Date.parse(s.endsAt)>Date.parse(a.startsAt));if(hasCover){const proceed=window.confirm('A replacement shift may already be published for these dates. Removing the absence will NOT automatically restore the original employee or cancel the replacement. Choose OK to keep the existing assignment and remove the absence, or Cancel to review the schedule first.');if(!proceed)return;}void run(async()=>{await request(`scheduling/unavailability/${a.id}`,'DELETE');setMessage(hasCover?'Exception removed. Existing replacement shifts were kept. Review the planner before restoring the original employee.':'Exception removed. Existing published assignments are unchanged.')})}}>Remove exception</button></div>)}</section></div>}</div>;
}
